import {ORCHARD_SCORES,orchardSceneHTML} from './tide-orchard-vfx.js?v=0.90.47';
import {salvationHTML} from './salvation.js?v=0.87.0';
import {MOVE_SCENES,moveSceneHTML} from './move-scene-renderer.js?v=0.87.0';
import {SIGNATURE_EFFECTS,signatureHTML} from './signature-effects.js?v=0.87.0';
export const PALETTES={NORMAL:'#ffe7b4',FIRE:'#ff7848',WATER:'#65cfff',ELECTRIC:'#ffe45b',GRASS:'#a4ed75',ICE:'#b6f5ff',FIGHTING:'#ffab6b',POISON:'#dc8bff',GROUND:'#d6a36b',FLYING:'#b3e8ff',PSYCHIC:'#ff92de',BUG:'#d0f077',ROCK:'#dabf95',GHOST:'#b9a0ff',DRAGON:'#9f8bff',DARK:'#c36de4',STEEL:'#c3e8ee',FAIRY:'#ffb7e8'};
const symbols={NORMAL:'M0,-12 4,-4 13,0 4,4 0,13 -4,4 -13,0 -4,-4Z',FIRE:'M0,-17Q15,-3 7,11Q0,20 -9,9Q-16,0 -6,-9Q-8,4 0,3Z',WATER:'M0,-16Q18,5 8,13Q0,21 -9,12Q-17,4 0,-16Z',ELECTRIC:'M3,-19 -11,3 -1,3 -4,20 12,-4 3,-4Z',GRASS:'M-12,13Q-18,-15 15,-15Q16,12 -12,13ZM-10,10 10,-10',ICE:'M0,-17 10,-5 8,10 0,18 -8,10 -10,-5Z M0,-17V18 M-10,-5 10,-5 M-8,10 8,10',FIGHTING:'M-12,-8 -8,-15 -2,-14 3,-17 10,-12 14,-3 10,13 -9,13 -15,2Z',POISON:'M0,-14A14,14 0 1,0 0,14A14,14 0 1,0 0,-14Z M-5,-3A2,2 0 1,0 -5,1 M5,-3A2,2 0 1,0 5,1 M-6,7Q0,3 6,7',GROUND:'M-15,10 -10,-6 0,-14 13,-4 16,12 -4,16Z',FLYING:'M-13,15Q-14,-16 15,-16Q17,7 -13,15ZM-10,11 12,-13M-5,4 8,4',PSYCHIC:'M-18,0Q0,-22 18,0Q0,22 -18,0ZM0,-7A7,7 0 1,0 0,7A7,7 0 1,0 0,-7',BUG:'M0,-9Q-16,-21 -15,-3Q-14,6 0,2Q14,6 15,-3Q16,-21 0,-9ZM0,-9V16',ROCK:'M-14,-7 -2,-15 15,-8 10,12 -6,17 -16,5Z M-2,-15 1,2 10,12 M1,2 -16,5',GHOST:'M-13,15V-2Q-13,-18 0,-18Q13,-18 13,-2V15L6,9 0,16 -6,9Z',DRAGON:'M0,-18 6,-8 16,-12 12,0 18,7 5,8 0,18 -5,8 -18,7 -12,0 -16,-12 -6,-8Z',DARK:'M8,-17Q-13,-9 -3,9Q0,17 14,14Q-17,25 -17,-1Q-16,-20 8,-17Z',STEEL:'M-4,17 -8,10 7,-17 14,-20 14,-10 0,13Z',FAIRY:'M0,-18 5,-5 18,0 5,5 0,18 -5,5 -18,0 -5,-5Z'};
export function effectSpec(move={},result={}){if(ORCHARD_SCORES[move.id])return {...ORCHARD_SCORES[move.id],hit:!result.missed&&!result.skipped&&!result.immune};if(move.salvation)return {id:move.id,type:move.type_id,style:'salvation',individual:true,signature:true,sequence:'caster-light → restraint → mercy seal',color:'#ffe9ad',accent:'#b48a38',duration:1600,impact:.6,hit:!result.missed&&!result.skipped&&!result.immune};const signature=SIGNATURE_EFFECTS[move.id];if(signature)return {...signature,type:move.type_id,status:!move.power,hit:!result.skipped&&!result.missed&&!result.immune,critical:!!result.critical};const scene=MOVE_SCENES[move.id];if(scene)return {...scene,color:PALETTES[move.type_id],status:!move.power,hit:!result.skipped&&!result.missed&&!result.immune,critical:!!result.critical,individual:true};const effects=move.effects||[],text=(move.name+' '+(move.authored_visual_action||'')).toLowerCase(),has=id=>effects.some(e=>e.effect_id===id);let style;
 if(!move.power)style=has('heal')||has('heal_by_format')||has('cure_major_status')?'bloom':has('screen')||has('next_hit_damage_multiplier')||/guard|ward|wall|barrier|shell/.test(text)?'shield':has('weather')||has('terrain')||has('recurring_status')?'field':has('inflict_status')||has('incoming_type_damage_multiplier')||has('disable_last_move')?'seal':/veil|haze|mist/.test(text)?'mist':'orbit';
 else {const text=move.name.toLowerCase();style=has('drain')?'drain':/feint/.test(text)?'feint':move.priority>0||/dash|rush|pounce|blitz|intercept/.test(text)?'dash':/beam|lance|ray|pierce/.test(text)?'beam':/fang|bite|maw/.test(text)?'fang':/slash|claw|cut|blade|lash|crescent/.test(text)?'slash':/wave|pulse|roar|cry|chorus|ring/.test(text)?'wave':/spiral|vortex|coil|cyclone/.test(text)?'vortex':/spire|pillar|cairn|crown/.test(text)?'pillar':/kick|blow|jab|elbow|strike|throw|crash/.test(text)?'impact':'nova';}
 return {id:move.id||0,type:move.type_id||'NORMAL',style,color:PALETTES[move.type_id]||PALETTES.NORMAL,status:!move.power,hit:!result.skipped&&!result.missed&&!result.immune,critical:!!result.critical,variant:(move.id||0)%7,particles:8+(move.id||0)%9,duration:({beam:1300,slash:900,impact:950,dash:850,fang:1200,wave:1400,vortex:1600,pillar:1500,nova:1350,feint:1200,drain:1500,bloom:1500,shield:1200,field:1600,orbit:1300,seal:1450,mist:1400})[style],impact:move.power?.54:.35};}
export function effectHTML(move,result={}){if(move.salvation)return salvationHTML({...move,category:result.category||move.category},result);const s=effectSpec(move,result);if(!s.hit)return `<div class="fx-message">${result.missed?'MISS':result.immune?'IMMUNE':result.selfDamage?'CONFUSED':'ACTION STOPPED'}</div>`;
 const glyph=(i,cls='vfx-mote')=>`<svg class="${cls}" viewBox="-24 -24 48 48" aria-hidden="true" style="--i:${i};--angle:${i*137.5+s.variant*17}deg;--reach:${52+i%4*20}px;--bend:${(i%2?1:-1)*(20+i*3)}px"><path d="${symbols[s.type]}"/>${s.type==='GHOST'?'<ellipse cx="-5" cy="-4" rx="2" ry="4" class="ghost-eye"/><ellipse cx="5" cy="-4" rx="2" ry="4" class="ghost-eye"/><ellipse cx="0" cy="5" rx="3" ry="5" class="ghost-eye"/>':''}</svg>`;
 const number=result.damage?`<div class="impact-number ${result.critical?'critical-number':''}" style="animation-delay:${s.duration*s.impact}ms">−${result.damage}${result.critical?'<small>CRITICAL</small>':''}</div>`:'';
 if(s.orchard)return orchardSceneHTML(move,result);
 if(s.signature)return signatureHTML(move,result)+number;
 if(s.individual)return moveSceneHTML(move,result,s.color)+number;
 const part=name=>`<i class="vfx-${name}"></i>`,waves=n=>Array.from({length:n},(_,i)=>`<i class="vfx-ring" style="--i:${i}"></i>`).join(''),motes=n=>Array.from({length:n},(_,i)=>glyph(i)).join(''),cuts=n=>Array.from({length:n},(_,i)=>`<i class="vfx-cut" style="--i:${i}"></i>`).join(''),shield='<svg class="vfx-shield" viewBox="0 0 100 120"><path d="M50 4 94 24 88 75Q75 101 50 114Q25 101 12 75L6 24Z"/><path d="M50 15V101M18 32 82 32M22 69 78 69"/></svg>';
 const parts={beam:part('charge')+part('projectile')+cuts(1)+motes(4),slash:cuts(2+s.variant%3)+motes(4+s.variant%3),impact:part('flash')+waves(1)+motes(7),dash:cuts(2+s.variant%3)+part('projectile'),fang:cuts(2)+motes(4),wave:waves((move.power||0)>=75?4:2)+motes(3),vortex:waves(2)+motes(10),pillar:motes(7)+waves(1),nova:part('charge')+part('projectile')+part('flash')+waves(2)+motes(8),feint:cuts(2)+motes(4),drain:part('projectile')+motes(6)+waves(1),bloom:motes(8)+waves(1),shield:shield+motes(4),field:waves(2)+motes(12),orbit:motes(7)+waves(1),seal:waves(2)+motes(4),mist:waves(1)+motes(5)};
 const subtype=/kick/i.test(move.name)?'kick':/jab|sting|needle/i.test(move.name)?'jab':/crash|break|throw/i.test(move.name)?'crash':/shot|arrow/i.test(move.name)?'shot':'';
 const weather=move.effects?.find(e=>e.effect_id==='weather')?.weather?.toLowerCase()||'';
 return `<div class="battle-vfx motif-${s.type.toLowerCase()} action-${s.style} ${weather?'field-weather-'+weather:''} ${subtype?'sub-'+subtype:''} ${(move.power||0)>=85?'heavy-force':''} ${s.critical?'critical-fx':''}" data-fx-move="${s.id}" data-fx-style="${s.style}" style="--fx-color:${s.color};--fx-duration:${s.duration}ms;--twist:${s.variant*23}deg">${parts[s.style]||parts.nova}</div>${number}`;
}
